+import ExcelJS from "exceljs";
+import JSZip from "jszip";
+import { z } from "zod";
+import { ResearchDataset, type ResearchRecord } from "@reqflow/core";
+
+export const FEEDBACK_COLUMNS = [
+  "ID", "Source", "Brand", "Sales Description", "Country", "Derivate (e-code)",
+  "Engine Type", "Feedback Type", "Customer Feedback", "Vfc level2 3 Name",
+  "Vfc level2 Name", "Vfc level3 Name", "Source URL", "Published At",
+  "Published Precision", "Retrieved At", "Language", "Research Agent",
+  "Original Source ID", "Original Record ID", "Fundstelle / Kontextbezug",
+  "Source ID", "Run IDs", "Limitations", "Original Feedback ID", "Source Sheet", "Source Row",
+];
+
+const SourceAssociation = z.object({
+  headers: z.array(z.string()),
+  values: z.array(z.unknown()),
+  sheet: z.string(),
+  row: z.number().int().positive(),
+}).refine((association) => association.headers.length === association.values.length,
+  "Source association headers and values must have equal length");
+
+function original(record: ResearchRecord, key: string): unknown {
+  const supplied = record.metadata.originalFields;
+  if (supplied && typeof supplied === "object" && Object.hasOwn(supplied, key))
+    return (supplied as Record<string, unknown>)[key];
+  return Object.hasOwn(record.metadata, key) ? record.metadata[key] : undefined;
+}
+
+function serializedText(value: unknown): string {
+  return value == null ? "" : typeof value === "string" ? value
+    : typeof value === "object" ? JSON.stringify(value) : String(value);
+}
+
+export function safeSpreadsheetText(value: unknown): string {
+  const text = serializedText(value);
+  return /^[\s\u0000-\u001f]*[=+@-]/.test(text) ? `'${text}` : text;
+}
+
+interface ExportRow {
+  values: unknown[];
+  recordId?: string;
+  sourceId?: string;
+}
+
+function feedbackRows(dataset: ResearchDataset): ExportRow[] {
+  const sources = new Map(dataset.sources.map((source) => [source.id, source]));
+  return dataset.records.filter((record) => record.recordType === "feedback").flatMap((record) => {
+    const parsed = z.array(SourceAssociation).safeParse(record.metadata.sourceAssociations ?? []);
+    if (!parsed.success) throw new Error(`Invalid source association for record ${record.id}: ${parsed.error.message}`);
+    const associations = parsed.data.length ? parsed.data : [undefined];
+    return associations.map((association) => {
+      // Missing columns in one supplied row must not borrow values from another row or attribution.
+      const field = (key: string): unknown => association
+        ? association.values[association.headers.indexOf(key)] : original(record, key);
+      return {
+        recordId: record.id,
+        sourceId: record.sourceId,
+        values: [
+          record.id, field("Source") ?? sources.get(record.sourceId)?.publisher ?? record.provider,
+          field("Brand"), field("Sales Description"), field("Country"),
+          field("Derivate (e-code)"), field("Engine Type"), field("Feedback Type"),
+          field("Customer Feedback") ?? record.text, field("Vfc level2 3 Name"),
+          field("Vfc level2 Name"), field("Vfc level3 Name"), record.originalUrl,
+          record.publishedAt, record.datePrecision, record.retrievedAt, record.language,
+          record.collectingAgents.join(", "), record.originalSourceId, record.originalRecordId,
+          association ? `${association.sheet}!row ${association.row}` : record.locator ?? record.parentId ?? record.threadId,
+          record.sourceId, record.runIds.join(", "), record.limitations.join("\n"),
+          association ? field("ID") : record.metadata.feedbackId ?? original(record, "ID"),
+          association?.sheet, association?.row,
+        ],
+      };
+    });
+  });
+}
+
+export function exportResearchJson(input: ResearchDataset): string {
+  return JSON.stringify(ResearchDataset.parse(input), null, 2);
+}
+
+export function exportResearchCsv(input: ResearchDataset): string {
+  const data = ResearchDataset.parse(input);
+  const quote = (value: unknown) => `"${safeSpreadsheetText(value).replaceAll('"', '""')}"`;
+  return "\ufeff" + [FEEDBACK_COLUMNS, ...feedbackRows(data).map((row) => row.values)]
+    .map((row) => row.map(quote).join(",")).join("\r\n");
+}
+
+const CELL_LIMIT = 32767;
+// ExcelJS removes these controls; XML 1.0 cannot carry most of them verbatim.
+const UNSAFE_XML = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f\ufffe\uffff]/u;
+const OVERFLOW_COLUMNS = [
+  "Record ID", "Source ID", "Sheet", "Row", "Column", "Column Name",
+  "Segment Order", "Segment Count", "Original Segment", "Original Segment JSON", "Serialization",
+];
+
+function serializedSegments(text: string): string[] {
+  const segments: string[] = [];
+  let segment = "", jsonLength = 2;
+  // Iterate code points so a surrogate pair is never split. Bound both the guarded display
+  // and the JSON string (quotes, backslashes and controls can expand during serialization).
+  for (const character of text) {
+    const encodedLength = JSON.stringify(character).length - 2;
+    if (segment.length + character.length > CELL_LIMIT - 1 || jsonLength + encodedLength > CELL_LIMIT) {
+      segments.push(segment);
+      segment = "";
+      jsonLength = 2;
+    }
+    segment += character;
+    jsonLength += encodedLength;
+  }
+  if (segment) segments.push(segment);
+  return segments;
+}
